  var layer = {"version":"cuz01-v1","scope":"Bakara 2:1-141","status":"verified-cuz01","audio_source":"Mazlum Kiper · 1. cüz · Fikriyat","audio_source_url":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","verses":{"2:1":{"sure_no":2,"ayet_no":1,"arapca":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ الٓمٓ","meal_tr":"Elif, Lâm, Mîm.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Elif Lâm Mîm.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":44.58,"audio_end":48.74,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:2":{"sure_no":2,"ayet_no":2,"arapca":"ذَٰلِكَ ٱلْكِتَـٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ","meal_tr":"İşte sana o Kitap! Kuşku,çelişme, tutarsızlık yok onda. Bir kılavuzdur o, korunup sakınanlar için.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bu, kendisinde şüphe olmayan kitaptır. Allah'a karşı gelmekten sakınanlar için yol göstericidir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":48.74,"audio_end":57.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:3":{"sure_no":2,"ayet_no":3,"arapca":"ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ","meal_tr":"Ki onlar, gayba inananlar, namazı kılanlardır. Ve kendilerine rızk olarak verdiklerimizden, başkalarına pay çıkaranlardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar gaybe inanırlar, namazı dosdoğru kılarlar, kendilerine rızık olarak verdiğimizden de Allah yolunda harcarlar.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":57.26,"audio_end":66.68,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:4":{"sure_no":2,"ayet_no":4,"arapca":"وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ","meal_tr":"Hem sana vahyedilene hem de senden önce vahyedilene inananlardır onlar. Âhıreti gereğince kavrayıp anlayanlar da onlardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar sana indirilene de, senden önce indirilenlere de inanırlar. Ahirete de kesin olarak inanırlar.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":66.68,"audio_end":75.28,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:5":{"sure_no":2,"ayet_no":5,"arapca":"أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","meal_tr":"İşte bunlardır Rablerinden bir hidayet üzere olanlar, işte bunlardır gerçek anlamda kurtuluşu bulanlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İşte onlar Rab'lerinden (gelen) bir doğru yol üzeredirler ve kurtuluşa erenler de işte onlardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":75.28,"audio_end":84.06,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:6":{"sure_no":2,"ayet_no":6,"arapca":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ","meal_tr":"Şu bir gerçek ki, o küfre batmış olanları sen korkutsan da korkutmasan da onlar için aynıdır; iman etmezler.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Küfre saplananlara gelince, onları uyarsan da, uyarmasan da, onlar için birdir, inanmazlar.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":84.06,"audio_end":91.48,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:7":{"sure_no":2,"ayet_no":7,"arapca":"خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَـٰرِهِمْ غِشَـٰوَةٌ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ","meal_tr":"Allah onların kalpleri, kulakları üzerine mühür basmıştır. Onların kafa gözleri üstünde de bir perde vardır. Onlar için korkunç bir azap öngörülmüştür.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Allah onların kalplerini ve kulaklarını mühürlemiştir. Gözleri üzerinde de bir perde vardır. Onlar için büyük bir azap vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":91.48,"audio_end":102.28,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:8":{"sure_no":2,"ayet_no":8,"arapca":"وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ","meal_tr":"İnsanlar içinden bazıları vardır, \"Allah'a ve âhıret gününe inandık\" derler ama onlar inanmış değillerdir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İnsanlardan, inanmadıkları halde, \"Allah'a ve ahiret gününe inandık\" diyenler de vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":102.28,"audio_end":110.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:9":{"sure_no":2,"ayet_no":9,"arapca":"يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ","meal_tr":"Allah'ı ve inanmış olanları aldatma yoluna giderler. Gerçekte ise onlar öz benliklerinden başkasını aldatmıyorlar. Ne var ki, bunun farkında olamıyorlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bunlar Allah'ı ve mü'minleri aldatmaya çalışırlar. Oysa sadece kendilerini aldatırlar da farkında değillerdir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":110.22,"audio_end":119.72,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:10":{"sure_no":2,"ayet_no":10,"arapca":"فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ","meal_tr":"Kalplerinde bir hastalık vardır da Allah onları hastalık yönünden daha ileri götürmüştür. Ve onlar için, yalancılık etmiş olmaları yüzünden acıklı bir azap öngörülmüştür.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Kalplerinde münafıklıktan kaynaklanan bir hastalık vardır. Allah da onların hastalıklarını artırmıştır. Söyledikleri yalana karşılık da onlara elem dolu bir azap vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":119.72,"audio_end":134.46,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:11":{"sure_no":2,"ayet_no":11,"arapca":"وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ","meal_tr":"Onlara, \"Yeryüzünde bozgun çıkartmayın\" dendiğinde, \"Tam tersine, bizler barış ve esenlik getirenleriz\" demişlerdir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bunlara, \"Yeryüzünde fesat çıkarmayın\" denildiğinde, \"Biz ancak ıslah edicileriz!\" derler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":134.46,"audio_end":142.5,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:12":{"sure_no":2,"ayet_no":12,"arapca":"أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَـٰكِن لَّا يَشْعُرُونَ","meal_tr":"Dikkat edin, gerçekte onlar, bozgun getirenlerin ta kendileridir de bunun bilincinde olmuyorlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İyi bilin ki, onlar bozguncuların ta kendileridir. Fakat farkında değillerdir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":142.5,"audio_end":149.34,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:13":{"sure_no":2,"ayet_no":13,"arapca":"وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَـٰكِن لَّا يَعْلَمُونَ","meal_tr":"Onlara, \"İnsanların inandığı gibi siz de inanın\" dendiğinde, \"Yani biz de kafası çalışmayan zavallılar gibi inanalım mı?\" derler. Haberiniz olsun ki, kafası çalışmayan düşük seviyeliler onların ta kendileridir; fakat bilmiyorlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlara, \"İnsanların inandıkları gibi siz de inanın\" denildiğinde ise, \"Biz de akılsızlar gibi iman mı edelim?\" derler. İyi bilin ki, asıl akılsızlar kendileridir, fakat bilmezler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":149.34,"audio_end":163.32,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:14":{"sure_no":2,"ayet_no":14,"arapca":"وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَـٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ","meal_tr":"Bunlar iman etmiş olanlarla yüz yüze geldiklerinde, \"îman ettik\" derler. Kendi şeytanlarıyla baş başa kaldıklarında ise söyledikleri şudur: \"Hiç kuşkunuz olmasın biz sizinleyiz. Gerçek olan şu ki, biz alay edip duran kişileriz.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İman edenlerle karşılaştıkları zaman, \"İnandık\" derler. Fakat şeytanlarıyla (münafık dostlarıyla) yalnız kaldıkları zaman, \"Şüphesiz, biz sizinle beraberiz. Biz ancak onlarla alay ediyoruz\" derler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":163.32,"audio_end":180.66,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:15":{"sure_no":2,"ayet_no":15,"arapca":"ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ","meal_tr":"Allah onlarla alay ediyor ve onları, kendi azgınlıkları içinde bocalar bir halde sürüklüyor.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Gerçekte Allah onlarla alay eder (alaylarından dolayı onları cezalandırır); azgınlıkları içinde bocalayıp dururlarken onlara mühlet verir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":180.66,"audio_end":192.12,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:16":{"sure_no":2,"ayet_no":16,"arapca":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ","meal_tr":"İşte bunlar, doğruluk ve aydınlığı verip karanlık ve sapıklığı satın aldılar da ticaretleri hiç bir kazanç sağlamadı. Bir yol yordama girebilmiş de değillerdir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İşte onlar, hidayete karşılık sapıklığı satın almış kimselerdir. Bu yüzden alışverişleri onlara kâr getirmemiş ve (sonuçta) doğru yolu bulamamışlardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":192.12,"audio_end":205.38,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:17":{"sure_no":2,"ayet_no":17,"arapca":"مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَـٰتٍ لَّا يُبْصِرُونَ","meal_tr":"Onların durumu şu kişinin durumuna benzer: Bir ateş tutuşturmak istedi. Ateş, çevresindekileri aydınlattığında, Allah onların ışığını giderdi ve onları karanlıklar içinde bıraktı; artık görmezler.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onların durumu, (geceleyin) ateş yakan kimsenin durumuna benzer: Ateş tam çevresini aydınlattığı sırada Allah ışıklarını yok ediverir de onları göremez bir şekilde karanlıklar içinde bırakıverir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":205.38,"audio_end":222.12,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:18":{"sure_no":2,"ayet_no":18,"arapca":"صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ","meal_tr":"Sağırdırlar, dilsizdirler, kördürler. Onlar artık dönmezler.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar, sağırdırlar, dilsizdirler, kördürler. Artık (hakka) dönmezler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":222.12,"audio_end":228.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:19":{"sure_no":2,"ayet_no":19,"arapca":"أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَـٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَـٰفِرِينَ","meal_tr":"Yahut gökten boşalan bir yağmur haline benzer ki onda karanlıklar var, bir gök gürlemesi var, bir şimşek var. Yıldırımlar yüzünden ölüm korkusuyla parmaklarını kulaklarına tıkarlar. Allah Muhît'dir, küfre sapanları çepeçevre kuşatmıştır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Yahut onların durumu, gökten yoğun karanlıklar içinde gök gürültüsü ve şimşekle sağanak halinde boşanan yağmura tutulmuş kimselerin durumu gibidir. Ölüm korkusuyla, yıldırım seslerinden parmaklarını kulaklarına tıkarlar. Oysa Allah, kâfirleri çepeçevre kuşatmıştır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":228.26,"audio_end":250.94,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:20":{"sure_no":2,"ayet_no":20,"arapca":"يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَـٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَـٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","meal_tr":"Şimşek, neredeyse gözlerini çarpıp götürüverecek. Kendilerine her aydınlık sunduğunda, orada yürürler. Üzerlerine karanlık binince çakılıp kalırlar. Eğer Allah dileseydi, işitme güçlerini de gözlerini de elbette alıp götürürdü. Çünkü Allah her şeye Kadîr'dir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Şimşek neredeyse gözlerini alıverecek. Önlerini her aydınlatışında ışığında yürürler. Karanlık çökünce dikilip kalırlar. Allah dileseydi, elbette onların işitme ve görme duyularını giderirdi. Şüphesiz Allah her şeye hakkıyla gücü yetendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":250.94,"audio_end":272.66,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:21":{"sure_no":2,"ayet_no":21,"arapca":"يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ","meal_tr":"Ey insanlar! Sizi de sizden öncekileri de yaratan Rabb'inize ibadet edin ki, korunabilesiniz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize ibadet edin ki, Allah'a karşı gelmekten sakınasınız.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":272.66,"audio_end":281.24,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:22":{"sure_no":2,"ayet_no":22,"arapca":"ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ","meal_tr":"O Rab ki, yeri sizin için bir döşek, göğü de bir bina yaptı. Ve gökten bir su indirdi de onunla sizin için meyvelerden / ürünlerden bir rızk çıkardı. Artık bilip durduğunuz halde Allah'a ortaklar koşmayın.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"O, yeri sizin için döşek, göğü de bina yapan, gökten su indirip onunla size rızık olarak çeşitli ürünler çıkarandır. Öyleyse siz de bile bile Allah'a ortaklar koşmayın.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":281.24,"audio_end":296.08,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:23":{"sure_no":2,"ayet_no":23,"arapca":"وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ","meal_tr":"Eğer kulumuza indirdiğimizden kuşku içindeyseniz, hadi onun benzerinden bir sure getirin! Allah dışındaki destekçilerinizi / tanıklarınızı da çağırın. Eğer doğru sözlü kişilerseniz...","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Eğer kulumuza (Muhammed'e) indirdiğimiz (Kur'an) hakkında şüphede iseniz, haydin onun benzeri bir sûre getirin ve eğer doğru söyleyenler iseniz, Allah'tan başka şahitlerinizi çağırın (ve bunu ispat edin).","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":296.08,"audio_end":312.64,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:24":{"sure_no":2,"ayet_no":24,"arapca":"فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَـٰفِرِينَ","meal_tr":"Eğer yapamazsanız - ki asla yapamayacaksınız - korkun o ateşten ki yakıtı insanlarla taşlardır. Küfre sapanlar için hazırlanmıştır o.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Eğer, yapamazsanız -ki hiçbir zaman yapamayacaksınız- o halde yakıtı insanlarla taşlar olan ateşten sakının. O ateş kafirler için hazırlanmıştır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":312.64,"audio_end":325.02,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:25":{"sure_no":2,"ayet_no":25,"arapca":"وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا۟ هَـٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهًا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَـٰلِدُونَ","meal_tr":"İman edip hayra ve barışa yönelik değerler üretenlere şunu müjdele: Kendileri için, altlarından ırmaklar akan cennetler olacaktır. Onlardaki herhangi bir meyvadan bir rızk olarak her nasiplendirildiklerinde, şöyle diyeceklerdir: \"İşte bu, daha önce rızklandırıldığımız şey!\" Bu rızk onlara buna benzer şekilde verilmişti. Onlar için orada tertemiz eşler de vardır. Ve onlar orada sürekli kalacaklardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İman edip salih ameller işleyenlere, kendileri için; içinden ırmaklar akan cennetler olduğunu müjdele. Cennetlerin meyvelerinden kendilerine her rızık verilişinde, \"Bu (tıpkı) daha önce (dünyada iken) bize verilen rızık!\" diyecekler. Halbuki bu rızık onlara (dünyadakine) benzer olarak verilmiştir. Onlar için orada tertemiz eşler de vardır. Onlar orada ebedi kalacaklardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":325.02,"audio_end":357.24,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:26":{"sure_no":2,"ayet_no":26,"arapca":"إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۘ يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ","meal_tr":"Şu bir gerçek ki Allah, bir sivrisineği hatta onun da üstündeki bir varlığı örnek göstermekten sıkılmaz. Böyle bir durumda, inananlar bilirler ki o, Rablerinden bir gerçektir. Küfre sapmışlar ise şöyle derler: \"Allah, bunu örnek vermekle ne demek istedi?\" Allah onunla birçoğunu saptırır, birçoğunu da onunla doğruya ve güzele kılavuzlar. Allah onunla fâsıklardan başkasını saptırmaz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Allah bir sivrisineği, ondan daha da ötesi bir varlığı örnek olarak vermekten çekinmez. İman edenler onun, Rablerinden (gelen) bir gerçek olduğunu bilirler. Küfre saplananlar ise, \"Allah örnek olarak bununla neyi kastetmiştir?\" derler. (Allah) onunla bir çoklarını saptırır, bir çoklarını da doğru yola iletir. Onunla ancak fasıkları saptırır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":357.24,"audio_end":385.64,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:27":{"sure_no":2,"ayet_no":27,"arapca":"ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ","meal_tr":"O fâsıklar ki Allah'a verdikleri ahdi, onunla anlaşıp bağlandıktan sonra bozar, Allah'ın birleştirilmesini emrettiği şeyi keser ve yeryüzünde bozgun çıkarırlar. İşte bunlardır hüsrana uğrayanlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar, Allah'a verdikleri sözü, pekiştirilmesinden sonra bozan, Allah'ın korunmasını emrettiği bağları (iman, akrabalık, beşeri ve ahlâki bütün ilişkileri) koparan ve yeryüzünde bozgunculuk yapan kimselerdir. İşte onlar ziyana uğrayanların ta kendileridir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":385.64,"audio_end":407.6,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:28":{"sure_no":2,"ayet_no":28,"arapca":"كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَـٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ","meal_tr":"Allah'a nasıl nankörlük ediyorsunuz?! Siz ölülerdiniz, O sizi diriltti. Sizi yine öldürecek ve sonra diriltecektir. Nihayet O'na döndürüleceksiniz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Siz cansız (henüz yok) iken sizi dirilten (dünyaya getiren) Allah'ı nasıl inkar ediyorsunuz? Sonra sizleri öldürecek, sonra yine diriltecektir. En sonunda ona döndürüleceksiniz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":407.6,"audio_end":422.24,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:29":{"sure_no":2,"ayet_no":29,"arapca":"هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَـٰوَٰتٍ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ","meal_tr":"O Allah'tır ki, yeryüzündekilerin tümünü sizin için yarattı. Sonra göğe saltanat kurdu da onları yedi gök halinde düzenledi. O Alîm'dir, her şeyi çok iyi bilir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"O, yeryüzünde olanların hepsini sizin için yaratan, sonra göğe yönelip onları yedi gök halinde düzenleyendir. O, her şeyi hakkıyla bilendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":422.24,"audio_end":434.72,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:30":{"sure_no":2,"ayet_no":30,"arapca":"وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ","meal_tr":"Bir zamanlar Rabb'in meleklere: \"Ben, yeryüzünde bir halife atayacağım.\" demişti de onlar şöyle konuşmuşlardı: \"Orada bozgunculuk etmekte olan, kan döken birini mi atayacaksın? Oysaki bizler, seni hamd ile tespih ediyoruz; seni kutsayıp yüceltiyoruz.\" Allah şöyle dedi: \"Şu bir gerçek ki ben, sizin bilmediklerinizi bilmekteyim.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, Rabbin meleklere, \"Ben yeryüzünde bir halife yaratacağım\" demişti. Onlar, \"Orada bozgunculuk yapacak, kan dökecek birini mi yaratacaksın? Oysa biz sana hamdederek daima seni tesbih ve takdis ediyoruz.\" demişler, Allah da, \"Ben sizin bilmediğinizi bilirim\" demişti.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":434.72,"audio_end":457.74,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:31":{"sure_no":2,"ayet_no":31,"arapca":"وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَـٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَـٰٓؤُلَآءِ إِن كُنتُمْ صَـٰدِقِينَ","meal_tr":"Ve Âdem'e isimlerin tümünü öğretti. Sonra onları meleklere göstererek şöyle buyurdu: \"Hadi, haber verin bana şunların isimlerini, eğer doğru sözlüler iseniz.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Allah Adem'e bütün varlıkların isimlerini öğretti. Sonra onları meleklere göstererek, \"Eğer doğru söyleyenler iseniz, haydi bana bunların isimlerini bildirin\" dedi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":457.74,"audio_end":471.16,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:32":{"sure_no":2,"ayet_no":32,"arapca":"قَالُوا۟ سُبْحَـٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ","meal_tr":"Dediler ki: \"Yücedir şanın senin. Bize öğretmiş olduğunun dışında bilgimiz yok bizim. Sen, yalnız sen Alîm'sin, her şeyi en iyi şekilde bilirsin; Hakîm'sin, her şeyin bütün hikmetlerine sahipsin.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Melekler, \"Seni bütün eksikliklerden uzak tutarız. Senin bize öğrettiklerinden başka bizim hiçbir bilgimiz yoktur. Şüphesiz her şeyi hakkıyla bilen, her şeyi hikmetle yapan sensin\" dediler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":471.16,"audio_end":486.82,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:33":{"sure_no":2,"ayet_no":33,"arapca":"قَالَ يَـٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ ۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ","meal_tr":"Allah buyurdu: \"Ey Âdem, haber ver onlara onların adlarını.\" Adem onlara onların adlarını haber verince, Allah şöyle buyurdu: \"Dememiş miydim ben size! Ki ben, göklerin ve yerin gaybını en iyi bilenim. Ve ben, sizin açığa vurduklarınızı da saklayageldiklerinizi de en iyi biçimde bilmekteyim.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Allah şöyle dedi: \"Ey Adem! Onlara bunların isimlerini söyle.\" Adem, meleklere onların isimlerini bildirince Allah, \"Size, göklerin ve yerin gaybını şüphesiz ki ben bilirim, yine açığa vurduklarınızı da, gizli tuttuklarınızı da ben bilirim demedim mi?\" dedi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":486.82,"audio_end":508.7,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:34":{"sure_no":2,"ayet_no":34,"arapca":"وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَـٰفِرِينَ","meal_tr":"O vakit biz meleklere, \"Âdem'e secde edin\" demiştik de İblis dışında tümü secde etmişti. İblis yan çizmiş, kibre sapmış ve nankörlerden olmuştu.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani meleklere, \"Adem için saygı ile eğilin\" demiştik de İblis hariç bütün melekler hemen saygı ile eğilmişler, İblis (bundan) kaçınmış, büyüklük taslamış ve kâfirlerden olmuştu.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":508.7,"audio_end":524.58,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:35":{"sure_no":2,"ayet_no":35,"arapca":"وَقُلْنَا يَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ","meal_tr":"Ve Âdem'e şöyle buyurmuştuk: \"Ey Âdem, sen ve eşin cennete yerleşin ve ondan dilediğiniz yerde, bol bol yiyin. Ama şu ağaca yaklaşmayın, yoksa zulme sapanlardan olursunuz.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Dedik ki: \"Ey Adem! Sen ve eşin cennete yerleşin. Orada dilediğiniz gibi bol bol yiyin, ama şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":524.58,"audio_end":535.36,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:36":{"sure_no":2,"ayet_no":36,"arapca":"فَأَزَلَّهُمَا ٱلشَّيْطَـٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ","meal_tr":"Bunun üzerine şeytan onların ayaklarını kaydırdı da onları içinde bulundukları yerden çıkardı. Biz de şöyle buyurduk: \"Bir kısmınız bir kısmınıza düşman olarak aşağıya inin. Belli bir süreye kadar yeryüzünde sizin için bir bekleme yeri, bir nimet / bir yararlanma imkânı olacaktır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Derken, şeytan ayaklarını oradan kaydırdı. Onları içinde bulundukları konumdan çıkardı. Bunun üzerine biz de, \"Birbirinize düşman olarak inin. Sizin için yeryüzünde belli bir süre barınak ve yararlanma vardır\" dedik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":535.36,"audio_end":553.86,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:37":{"sure_no":2,"ayet_no":37,"arapca":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","meal_tr":"Bunun üzerine Âdem, Rabb'inden bazı kelimeler öğrenip belledi de O'na yöneldi. O da onun tövbesini kabul etti. Gerçekten de O, evet O, Tevvâb'dır, tövbeleri cömertçe kabul eder; Rahîm'dir, rahmetini cömertçe yayar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Derken, Adem (vahy yoluyla) Rabbinden birtakım kelimeler aldı, (onlarla amel edip Rabb'ine yalvardı. O da) bunun üzerine tövbesini kabul etti. Şüphesiz o, tövbeleri çok kabul edendir, çok bağışlayandır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":553.86,"audio_end":570.4,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:38":{"sure_no":2,"ayet_no":38,"arapca":"قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","meal_tr":"\"Hepiniz oradan aşağı inin.\" dedik. Benden size bir yol gösteriş ulaşır da kim bu yol gösterişime uyarsa artık böylelerine hiç bir korku yoktur. Onlar kederle de yüz yüze gelmeyeceklerdir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"İnin oradan (cennetten) hepiniz. Tarafımdan size bir yol gösterici (peygamber) gelir de kim ona uyarsa, onlar için herhangi bir korku yoktur, onlar üzülmeyeceklerdir\" dedik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":570.4,"audio_end":585.48,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:39":{"sure_no":2,"ayet_no":39,"arapca":"وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","meal_tr":"Nankörlüğe sapıp ayetlerimizi yalanlayanlara gelince onlar, ateşin dostu olacaklardır. Onlar orada sürekli kalacaklardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İnkâr edenler ve âyetlerimizi yalanlayanlara gelince, işte bunlar cehennemliktir. Onlar orada ebedî kalacaklardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":585.48,"audio_end":595.58,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:40":{"sure_no":2,"ayet_no":40,"arapca":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّـٰىَ فَٱرْهَبُونِ","meal_tr":"Ey İsrail oğulları! Size lütfettiğim nimetimi hatırlayın; bana verdiğiniz söze vefalı olun ki, ben de size ahdimde vefalı olayım. Ve yalnız benden korkun.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ey İsrailoğulları ! Size verdiğim nimeti hatırlayın. Bana verdiğiniz sözü yerine getirin ki ben de size verdiğim sözü yerine getireyim. Yalnız benden korkun.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":595.58,"audio_end":609.16,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:41":{"sure_no":2,"ayet_no":41,"arapca":"وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا وَإِيَّـٰىَ فَٱتَّقُونِ","meal_tr":"Beraberinizdekini doğrulayıcı olarak indirmiş bulunduğuma inanın. Onu ilk inkar eden siz olmayın. Benim ayetlerimi az bir bedel karşılığı satmayın. Ve yalnız benden sakının.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Elinizdeki Tevrat'ı tasdik edici olarak indirdiğimize (Kur'an'a) iman edin. Onu inkâr edenlerin ilki olmayın. Âyetlerimi az bir karşılığa değişmeyin ve bana karşı gelmekten sakının.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":609.16,"audio_end":624.1,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:42":{"sure_no":2,"ayet_no":42,"arapca":"وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ","meal_tr":"Hakkı batılla/saçmalık ve tutarsızlıkla kirletmeyin. Bilip durduğunuz halde gerçeği gizliyorsunuz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hakkı bâtılla karıştırıp da bile bile hakkı gizlemeyin.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":624.1,"audio_end":629.34,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:43":{"sure_no":2,"ayet_no":43,"arapca":"وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ","meal_tr":"Namazı kılın, zekâtı verin; rükû edenlerle birlikte rükû edin.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Namazı kılın, zekatı verin. Rükû edenlerle birlikte siz de rükû edin.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":629.34,"audio_end":634.14,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:44":{"sure_no":2,"ayet_no":44,"arapca":"أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَـٰبَ ۚ أَفَلَا تَعْقِلُونَ","meal_tr":"İnsanlara iyiyi ve güzeli emredip de öz benliklerinizi unutuyor musunuz? Üstelik de Kitap'ı okuyup durmaktasınız. Hâlâ aklınızı kullanmayacak mısınız?","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Siz Kitabı (Tevrat'ı) okuyup durduğunuz halde, kendinizi unutup başkalarına iyiliği mi emrediyorsunuz? (Yaptığınızın çirkinliğini) anlamıyor musunuz?","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":634.14,"audio_end":647.72,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:45":{"sure_no":2,"ayet_no":45,"arapca":"وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَـٰشِعِينَ","meal_tr":"Sabra ve namaza sarılarak yardım dileyin. Hiç kuşkusuz bu, kalbi ürperti duyanlardan başkasına çok ağır gelir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Sabrederek ve namaz kılarak (Allah'tan) yardım dileyin. Şüphesiz namaz, Allah'a derinden saygı duyanlardan başkasına ağır gelir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":647.72,"audio_end":659.1,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:46":{"sure_no":2,"ayet_no":46,"arapca":"ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ","meal_tr":"O ürperti duyanlar, Rablerine kavuşacaklarını düşünürler ve bilirler ki onlar, mutlaka O'na döneceklerdir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar, Rablerine kavuşacaklarını ve gerçekten ona döneceklerini çok iyi bilirler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":659.1,"audio_end":666.44,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:47":{"sure_no":2,"ayet_no":47,"arapca":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ","meal_tr":"Ey İsrailoğulları! Size lütfettiğim nimetimi, sizi âlemlere üstün kıldığımı hatırlayın.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ey İsrailoğulları! Size verdiğim nimetimi ve (bir zamanlar) sizi cümle âleme üstün kıldığımı hatırlayın.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":666.44,"audio_end":674.82,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:48":{"sure_no":2,"ayet_no":48,"arapca":"وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَـٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ","meal_tr":"Ve korkun o günden ki, hiç bir benlik bir başka benliğin herhangi bir şeyi için karşılık ödemez; hiç bir benlikten şefaat kabul edilmez, hiç bir benlikten fidye alınmaz. Ve onlara yardım da edilmez.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Öyle bir günden sakının ki o gün hiç kimse bir başkası adına bir şey ödeyemez. Hiçbir kimseden herhangi bir şefaat kabul olunmaz, fidye alınmaz. Onlara yardım da edilmez.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":674.82,"audio_end":688.74,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:49":{"sure_no":2,"ayet_no":49,"arapca":"وَإِذْ نَجَّيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ","meal_tr":"Sizi Firavun hanedanından kurtardığımızı da hatırlayın. Hani onlar size azabın en çirkiniyle kötülük ediyorlardı: Erkek çocuklarınızı boğazlıyorlar, kadınlarınızı diri bırakıyorlar/kadınlarınızın rahimlerini yoklayıp çocuk alıyorlar/kadınlarınıza utanç duyulacak şeyler yapıyorlardı. İşte bunda sizin için, Rabb'inizden gelen büyük bir ıstırap ve imtihan vardı.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, sizi azabın en kötüsüne uğratan, kadınlarınızı sağ bırakıp, oğullarınızı boğazlayan Firavun ailesinden kurtarmıştık. Bunda, size Rabbinizden (gelen) büyük bir imtihan vardı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":688.74,"audio_end":704.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:50":{"sure_no":2,"ayet_no":50,"arapca":"وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَـٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ","meal_tr":"Hani önünüzde denizi yarmıştık da sizi kurtarmış, Firavun hanedanını boğmuştuk. Siz de bunu bakıp görüyordunuz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, sizin için denizi yarmış, sizi kurtarmış, gözlerinizin önünde Firavun ailesini suda boğmuştuk.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":704.26,"audio_end":713.04,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:51":{"sure_no":2,"ayet_no":51,"arapca":"وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ","meal_tr":"Ve Mûsa ile kırk gece için sözleşmiştik de siz bunun ardından buzağıyı tanrı edinmiştiniz. Zulme sapmıştınız siz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, biz Mûsâ ile kırk gece için sözleşmiştik. Sizler ise onun ardından (kendinize) zulmederek bir buzağıyı tanrı edinmiştiniz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":713.04,"audio_end":723.76,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:52":{"sure_no":2,"ayet_no":52,"arapca":"ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ","meal_tr":"Belki şükredersiniz diye bunun ardından da sizi affetmiştik.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Sonra bunun ardından şükredesiniz diye sizi affetmiştik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":723.76,"audio_end":728.92,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:53":{"sure_no":2,"ayet_no":53,"arapca":"وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ","meal_tr":"İyiye ve güzele yol bulursunuz ümidiyle Mûsa'ya Kitap'ı ve furkanı/hakla batılı ayıran mesajı vermiştik.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, doğru yolu tutasınız diye Mûsâ'ya Kitab'ı (Tevrat'ı) ve Furkan'ı vermiştik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":728.92,"audio_end":735.76,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:54":{"sure_no":2,"ayet_no":54,"arapca":"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","meal_tr":"Hani Mûsa, toplumuna demişti ki: \"Ey toplumum, buzağıyı tanrı edinmenizle öz benliklerinize zulmettiniz. Hadi, yaratıcınıza, Bâri'nize tövbe edin; egolarınızı öldürün. Böyle yapmanız yaratıcınız katında sizin için daha iyidir; O sizin tövbelerinizi kabul eder. Hiç kuşkusuz O, evet O, tövbeleri çok kabul edendir, rahmeti sonsuz olandır.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Mûsâ kavmine dedi ki: \"Ey kavmim! Sizler, buzağıyı ilah edinmekle kendinize yazık ettiniz. Gelin yaratıcınıza tövbe edin de nefislerinizi öldürün (kendinizi düzeltin). Bu, Yaratıcınız katında sizin için daha iyidir. Böylece Allah da onların tövbesini kabul etti. Çünkü o, tövbeleri çok kabul edendir, çok merhametlidir.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":735.76,"audio_end":762.32,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:55":{"sure_no":2,"ayet_no":55,"arapca":"وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمْ تَنظُرُونَ","meal_tr":"Siz şunu da söylemiştiniz: \"Ey Mûsa! Biz, Allah'ı apaçık görmedikçe sana asla inanmayacağız.\" Bunun üzerine sizi yıldırım çarpmıştı, Ve siz bakıp duruyordunuz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani siz, \"Ey Mûsâ! Biz Allah'ı açıktan açığa görmedikçe sana asla inanmayız\" demiştiniz. Bunun üzerine siz bakıp dururken sizi yıldırım çarpmıştı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":762.32,"audio_end":774.58,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:56":{"sure_no":2,"ayet_no":56,"arapca":"ثُمَّ بَعَثْنَـٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ","meal_tr":"Sonra, ölümünüzün ardından sizi dirilttik ki, şükredebilesiniz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Sonra, şükredesiniz diye ölümünüzün ardından sizi tekrar dirilttik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":774.58,"audio_end":780.96,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:57":{"sure_no":2,"ayet_no":57,"arapca":"وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۖ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ","meal_tr":"Ve bulutu üstünüze gölgelik yaptık ve size kudret helvasıyla bıldırcın indirdik: \"rızk olarak size verdiklerimizin, en temizlerinden yiyin.\" dedik. Onlar zulmü bize yapmadılar, onlar kendi benliklerine zulmetmekteydiler.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bulutu üstünüze gölge yaptık. Size, kudret helvası ile bıldırcın indirdik. \"Verdiğimiz rızıkların iyi ve güzel olanlarından yiyin\" (dedik). Onlar (verdiğimiz nimetlere nankörlük etmekle) bize zulmetmediler fakat, kendilerine zulmediyorlardı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":780.96,"audio_end":801.86,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:58":{"sure_no":2,"ayet_no":58,"arapca":"وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَـٰيَـٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ","meal_tr":"Şöyle demiştik: \"Girin şu kente; orada, dilediğiniz yerde bol bol yiyin. Kapıdan secde ederek girin ve 'Affet bizi!' deyin ki, hatalarınızı bağışlayalım. Biz güzel davranıp, güzellik üretenlere daha fazlasını da veririz.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, \"Şu memlekete girin. Orada dilediğiniz gibi, bol bol yiyin. Kapısından eğilerek tevazu ile girin ve \"hıtta!\" (Ya Rabbi, bizi affet) deyin ki, biz de sizin hatalarınızı bağışlayalım. İyilik edenlere ise daha da fazlasını vereceğiz\" demiştik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":801.86,"audio_end":822.12,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:59":{"sure_no":2,"ayet_no":59,"arapca":"فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ","meal_tr":"Ne var ki zulme sapanlar, bir sözü kendilerine söylenmiş olandan başkasıyla değiştirdiler. Bunun üzerine biz, bu zalimler üstüne, ürettikleri kötülüklere karşılık olarak gökten bir pislik indirdik.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Derken, onların içindeki zalimler, sözü kendilerine söylenenden başka şekle soktular. Biz de haktan ayrılmaları sebebiyle o zalimlere gökten bir azap indirdik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":822.12,"audio_end":835.56,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:60":{"sure_no":2,"ayet_no":60,"arapca":"وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۖ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ","meal_tr":"Bir zamanlar Mûsa, toplumu için su istemişti de biz, \"Değneğinle şu taşa vur!\" demiştik. Taştan hemen oniki göze fışkırmıştı. Her bölük insan kendilerine özgü su kaynağını bilmişti. \"Allah'ın rızkından yiyin, için; yeryüzünde bozgunculuk yaparak şuna buna saldırmayın.\" demiştik.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, Mûsâ kavmi için su dilemişti. Biz de, \"Asanı kayaya vur\" demiştik, böylece kayadan on iki pınar fışkırmış, her boy kendi su alacağı pınarı bilmişti. \"Allah'ın rızkından yiyin, için. Yalnız, yeryüzünde bozgunculuk yaparak fesat çıkarmayın\" demiştik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":835.56,"audio_end":857.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:61":{"sure_no":2,"ayet_no":61,"arapca":"وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ۚ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ۗ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ۗ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","meal_tr":"Siz şöyle demiştiniz: \"Ey Mûsa, biz bir tek yemeğe asla dayanamayız, bizim için Rabb'ine dua et de bize yerin bitirdiklerinden, baklasından, acurundan, sarmısağından, mercimeğinden, soğanından çıkarıversin.\" Mûsa şöyle demişti: \"Siz daha aşağı bir nimeti daha üstün bir nimete mi değişmek istiyorsunuz? İnin bir kasabaya; istediğiniz sizin olacaktır.\" Ve üzerlerine zillet, eziklik ve yoksulluk damgası vuruldu, Allah'tan bir gazaba çarpıldılar. Bu böyle oldu, çünkü onlar Allah'ın ayetlerini inkâr ediyor ve haksız yere peygamberleri öldürüyorlardı. İsyan ettikleri için böyle oldu. Sınır tanımıyor, azgınlık yapıyorlardı.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, \"Ey Mûsâ! Biz bir çeşit yemeğe asla katlanamayız. O halde, bizim için Rabbine yalvar da, o bize yerden biten sebze, kabak, sarımsak, mercimek, soğan versin\" demiştiniz. O da size, \"İyi olanı düşük olanla değiştirmek mi istiyorsunuz? Öyle ise inin şehre! İstedikleriniz orada var\" demişti. Böylece zillet ve yoksulluk onları kapladı. Onlar, Allah'ın gazabına uğradılar. Bunun sebebi, onların; Allah'ın âyetlerini inkâr ediyor, peygamberleri de haksız yere öldürüyor olmaları idi. Bütün bunların sebebi ise, isyan etmek ve aşırı gitmekte oluşlarıydı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":857.26,"audio_end":902.08,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:62":{"sure_no":2,"ayet_no":62,"arapca":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","meal_tr":"Şu bir gerçek ki, iman edenlerden, Yahudilerden, Hıristiyanlardan, Sabîlerden Allah'a ve âhıret gününe inanıp barışa ve hayra yönelik iş yapanların, Rableri katında kendilerine has ödülleri olacaktır. Korku yoktur onlar için, tasalanmayacaklardır onlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Şüphesiz, inananlar (Müslümanlar) ile, Yahudiler, Hıristiyanlar ve Sâbiîlerden (her bir grubun kendi şeriatında) \"Allah'a ve ahiret gününe inanan ve salih ameller işleyenler için Rableri katında mükafat vardır; onlar korkuya uğramayacaklar, mahzun da olmayacaklardır\" (diye hükmedilmiştir).","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":902.08,"audio_end":927.24,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:63":{"sure_no":2,"ayet_no":63,"arapca":"وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ","meal_tr":"Hani, sizden şu şekilde kesin söz almış da Tûr'u üzerinize kaldırmıştık: \"Size verdiğimizi kuvvetle tutun ve içinde olanı hatırlayıp zikredin ki, sakınabilesiniz.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, (Tevrat ile amel edeceğinize dair) sizden sağlam bir söz almış, Tûr dağını da tepenize dikmiş ve \"Sakınasınız diye, size verdiğimiz Kitab'ı sıkı tutun, onun içindekileri düşünün (gafil olmayın)\" demiştik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":927.24,"audio_end":944.44,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:64":{"sure_no":2,"ayet_no":64,"arapca":"ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَـٰسِرِينَ","meal_tr":"Bunun ardından da yüz çevirip döndünüz. Eğer Allah'ın size lütfu ve rahmeti olmasaydı, kesinlikle hüsrana uğrayanlardan olacaktınız,","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bundan sonra yine yüz çevirdiniz. Allah'ın bol nimeti ve merhameti olmasaydı herhalde ziyana uğrayanlardan olurdunuz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":944.44,"audio_end":954.94,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:65":{"sure_no":2,"ayet_no":65,"arapca":"وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ","meal_tr":"Yemin olsun, içinizden Cumartesi gününde azgınlık yapanları siz bilirsiniz. Onlara şöyle dedik: \"Aşağılık maymunlar oluverin.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Şüphesiz siz, içinizden Cumartesi yasağını çiğneyenleri bilirsiniz. Biz onlara, \"Aşağılık maymunlar olun\" demiştik.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":954.94,"audio_end":965.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:66":{"sure_no":2,"ayet_no":66,"arapca":"فَجَعَلْنَـٰهَا نَكَـٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ","meal_tr":"Bu durumu, o zamankilere ve onların ardından geleceklere ibret dolu bir ceza, takva sahiplerine de bir öğüt yaptık.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Biz bunu, hem onu görenlere, hem de sonra geleceklere bir ibret ve Allah'a karşı gelmekten sakınanlara da bir öğüt kıldık.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":965.22,"audio_end":974.76,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:67":{"sure_no":2,"ayet_no":67,"arapca":"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً ۖ قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا ۖ قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَـٰهِلِينَ","meal_tr":"Mûsa, toplumuna dedi ki: \"Allah size, bir inek kesmenizi emrediyor.\" Dediler ki: \"Sen bizimle alay mı ediyorsun?\" Dedi ki: \"Cahillerden biri olmaktan Allah'a sığınırım.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani Mûsâ kavmine, \"Allah size bir sığır kesmenizi emrediyor\" demişti. Onlar da, \"Sen bizimle eğleniyor musun?\" demişlerdi. Mûsâ, \"Kendini bilmez cahillerden olmaktan Allah'a sığınırım\" demişti.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":974.76,"audio_end":991.06,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:68":{"sure_no":2,"ayet_no":68,"arapca":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ","meal_tr":"Şöyle konuştular: \"Çağır Rabb'ine bizim için, açıklasın bize neymiş o!\" Cevap verdi: \"O diyor ki, bahsettiğim ne yaşlıdır ne de körpe. İkisi arası bir inektir.\" Hadi size emredileni yapın!","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Bizim için Rabbine dua et de onun nasıl bir sığır olduğunu bize açıklasın.\" dediler. Mûsâ şöyle dedi: \"Rabbim diyor ki: O, ne yaşlı, ne körpe, ikisi arası bir sığırdır. Haydi emrolunduğunuz işi yapın.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":991.06,"audio_end":1007.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:69":{"sure_no":2,"ayet_no":69,"arapca":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّـٰظِرِينَ","meal_tr":"Şöyle dediler: \"Çağır Rabb'ine bizim için, neymiş onun rengi açıklasın bize.\" Cevap verdi: \"O diyor ki, bahsettiğim, sarı, rengi parlak bir inektir; seyredenlere mutluluk verir.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar, \"Bizim için Rabbine dua et de, rengi neymiş? açıklasın\" dediler. Mûsâ şöyle dedi: \"Rabbim diyor ki, o, sapsarı; rengi, bakanların içini açan bir sığırdır\" dedi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1007.26,"audio_end":1020.34,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:70":{"sure_no":2,"ayet_no":70,"arapca":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَـٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ","meal_tr":"Şöyle dediler \"Dua et Rabb'ine, açıklasın bize neymiş o! Çünkü bu inek, bizim gözümüzde başkalarıyla karıştı. Ve biz, Allah dilerse, doğruya ve güzele elbette kılavuzlanacağız.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Bizim için Rabbine dua et de onun nasıl bir sığır olduğunu bize açıklasın. Çünkü sığırlar, bizce, birbirlerine benzemektedir. Ama Allah dilerse elbet buluruz\" dediler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1020.34,"audio_end":1034,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:71":{"sure_no":2,"ayet_no":71,"arapca":"قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ۚ قَالُوا۟ ٱلْـَٔـٰنَ جِئْتَ بِٱلْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ","meal_tr":"Cevap verdi Mûsa: \"Allah diyor ki, bahsettiğim, boyunduruk yememiş bir inektir; toprağı sürmez, ekini sulamaz. Salma hayvandır. Alaca yoktur onda.\" Dediler ki: \"İşte şimdi gerçeği getirdin.\" Ve ardından onu boğazladılar, az kalsın yapmayacaklardı.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Mûsâ şöyle dedi: \"Rabbim diyor ki, o; çift sürmek, ekin sulamak için boyunduruğa vurulmamış, kusursuz, hiç alacası olmayan bir sığırdır\". Onlar, \"İşte, şimdi tam doğrusunu bildirdin\" dediler. Nihayet o sığırı kestiler. Neredeyse bunu yapmayacaklardı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1034,"audio_end":1055.46,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:72":{"sure_no":2,"ayet_no":72,"arapca":"وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ","meal_tr":"Siz bir adam öldürmüştünüz de onunla ilgili olarak çekişip duruyordunuz. Oysa ki Allah, sizin sakladıklarınızı ortaya çıkaracaktı.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, bir kimseyi öldürmüştünüz de suçu birbirinizin üstüne atmıştınız. Halbuki Allah gizlemekte olduğunuzu ortaya çıkaracaktı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1055.46,"audio_end":1065.84,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:73":{"sure_no":2,"ayet_no":73,"arapca":"فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ","meal_tr":"Şöyle dedik: \"Kesilen ineğin bir parçasıyla, öldürülen adama vurun.\" İşte böyle diriltir Allah ölüleri. Size ayetlerini gösteriyor ki, aklınızı işletebilesiniz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Sığırın bir parçası ile öldürülene vurun\" dedik. (Denileni yaptılar ve ölü dirildi.) İşte, Allah ölüleri böyle diriltir, düşünesiniz diye mucizelerini de size böyle gösterir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1065.84,"audio_end":1080.98,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:74":{"sure_no":2,"ayet_no":74,"arapca":"ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَـٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","meal_tr":"Sonra bunun ardından kalpleriniz yine kaskatı kesildi. Taş gibidir o. Belki daha da katıdır. Taşların bazıları var ki, ondan ırmaklar fışkırır. Bazıları var ki, çatır çatır yarılır da içinden su çıkar. Öylesi var ki, Allah korkusundan aşağılara düşer. Allah, yapıp durduklarınızdan gafil değildir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Sonra bunun ardından kalpleriniz yine katılaştı, taş gibi; hatta daha katı oldu. Çünkü taş vardır ki, içinden ırmaklar fışkırır. Taş vardır ki yarılır da içinden sular çıkar. Taş da vardır ki, Allah korkusuyla (yerinden kopup) düşer. Allah yaptıklarınızdan hiçbir zaman habersiz değildir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1080.98,"audio_end":1105.44,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:75":{"sure_no":2,"ayet_no":75,"arapca":"أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَـٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ","meal_tr":"Şimdi siz bunların size inanmalarını mı umuyorsunuz? Bunların içlerinden bir fırka vardı ki, Allah'ın kelamını dinliyorlar, sonra onu, kavramalarının ardından, bilip durdukları halde tahrif ediyorlardı.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Şimdi, bunların size inanacaklarını mı umuyorsunuz? Oysa içlerinden bir takımı, Allah'ın kelamını dinler, iyice anladıktan sonra, onu bile bile tahrif ederlerdi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1105.44,"audio_end":1118.9,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:76":{"sure_no":2,"ayet_no":76,"arapca":"وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ","meal_tr":"İnanmış olanlarla karşılaştıklarında, \"İnandık\" derler. Baş başa kaldıklarında ise şöyle konuşurlar: \"Allah'ın size açtığını, Rabb'iniz katında sizinle tartışmada kanıt yapsınlar diye onlara söylüyor musunuz? Aklınızı işletmeyecek misiniz?\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar iman edenlerle karşılaşınca, \"İman ettik\" derler. Birbirleriyle baş başa kaldıklarında da şöyle derler: \"Rabbinizin huzurunda delil olarak kullanıp sizi sustursunlar diye mi, Allah'ın (Tevrat'ta) size bildirdiklerini onlara söylüyorsunuz? (Bu kadarcık şeye) akıl erdiremiyor musunuz?\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1118.9,"audio_end":1144.06,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:77":{"sure_no":2,"ayet_no":77,"arapca":"أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ","meal_tr":"Bilmezler mi ki, Allah onların sakladıklarını da açıkladıklarını da çok iyi bilmektedir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar bilmiyorlar mı ki, Allah onların gizli tuttuklarını da bilir, açığa vurduklarını da.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1144.06,"audio_end":1151.18,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:78":{"sure_no":2,"ayet_no":78,"arapca":"وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَـٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ","meal_tr":"İçlerinde ümmî olanlar da vardır ki Kitap'ı bilmezler, sadece hayal ve kuruntu bilirler. Onlar yalnız sanıya saplanırlar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bunların bir de ümmî takımı vardır; Kitab'ı (Tevrat'ı) bilmezler. Onların bütün bildikleri bir sürü kuruntulardır. Onlar sadece zanda bulunurlar.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1151.18,"audio_end":1164.24,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:79":{"sure_no":2,"ayet_no":79,"arapca":"فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَـٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَـٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ","meal_tr":"Yazıklar olsun o kişilere ki, Kitap'ı kendi elleriyle yazarlar da sonra onunla basit bir karşılık satın alsınlar diye, \"İşte bu, Allah katındandır!\" derler. Vay haline onların, ellerinin yazdıkları yüzünden! Vay haline onların, kazanıp durdukları yüzünden!","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Vay o kimselere ki, elleriyle Kitab'ı yazarlar, sonra da onu az bir karşılığa değişmek için, \"Bu, Allah'ın katındandır\" derler. Vay ellerinin yazdıklarından ötürü onların haline! Vay kazandıklarından dolayı onların haline!","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1164.24,"audio_end":1182.2,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:80":{"sure_no":2,"ayet_no":80,"arapca":"وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ","meal_tr":"Dediler ki: \"Sayılı birkaç gün dışında ateş bize asla dokunmayacaktır.\" De ki: \"Allah'tan bir ahit mi aldınız! Allah, ahdine asla ters düşmez. Yoksa siz Allah'a isnat ederek, bilmediğiniz şeyleri mi söylüyorsunuz?\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bir de dediler ki: \"Bize ateş, sayılı birkaç günden başka asla dokunmayacaktır.\" Sen onlara de ki: \"Siz bunun için Allah'tan söz mü aldınız? -Eğer böyle ise, Allah verdiği sözden dönmez-. Yoksa siz Allah'a karşı bilemeyeceğiniz şeyleri mi söylüyorsunuz?\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1182.2,"audio_end":1203.06,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:81":{"sure_no":2,"ayet_no":81,"arapca":"بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَـٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","meal_tr":"İş onların sandığı gibi değil. Kötülük ve çirkinlik kazanan, suçu kendisini kuşatmış olan kişiler, ateşin dostudurlar. Sürekli kalacaklardır orada.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Evet, kötülük işleyip suçu benliğini kaplamış (ve böylece şirke düşmüş) olan kimseler var ya, işte onlar cehennemliklerdir. Onlar orada ebedi kalacaklardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1203.06,"audio_end":1216.64,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:82":{"sure_no":2,"ayet_no":82,"arapca":"وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","meal_tr":"İman edip hayra ve barışa yönelik işler yapanlar ise cennetin dostudurlar. Onlar da orada sürekli kalacaklardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İman edip salih ameller işleyenler ise cennetliklerdir. Onlar orada ebedi kalacaklardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1216.64,"audio_end":1224.36,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:83":{"sure_no":2,"ayet_no":83,"arapca":"وَإِذْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ","meal_tr":"İsrailoğulları'ndan şöyle bir söz de almıştık: Allah'tan başkasına ibadet etmeyin, anne-babaya, akrabaya, yetimlere, yoksullara iyilik ve güzellikle davranın. İnsanlara güzeli ve güzelliği söyleyin. Namazı kılın, zekâtı verin. Bütün bunlardan sonra siz, pek azınız müstesna, sırt çevirdiniz. Hâlâ da yüz çevirip duruyorsunuz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, biz İsrailoğulları'ndan, \"Allah'tan başkasına ibadet etmeyeceksiniz, anne babaya, yakınlara, yetimlere, yoksullara iyilik edeceksiniz, herkese güzel sözler söyleyeceksiniz, namazı kılacaksınız, zekatı vereceksiniz\" diye söz almıştık. Sonra pek azınız hariç, yüz çevirerek sözünüzden döndünüz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1224.36,"audio_end":1249.44,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:84":{"sure_no":2,"ayet_no":84,"arapca":"وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَـٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ","meal_tr":"Sizden şu sözü de almıştık: Birbirinizin kanını dökmeyeceksiniz. Birbirlerinizi yurtlarınızdan çıkarmayacaksınız. Bunu kabul etmiştiniz. Hâlâ da buna tanıklarsınız.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, \"Birbirinizin kanını dökmeyeceksiniz, birbirinizi yurtlarınızdan çıkarmayacaksınız\" diye de sizden kesin söz almıştık. Sonra bunu böylece kabul etmiştiniz. Kendiniz de buna hâlâ şahitlik etmektesiniz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1249.44,"audio_end":1267.84,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:85":{"sure_no":2,"ayet_no":85,"arapca":"ثُمَّ أَنتُمْ هَـٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَـٰرِهِمْ تَظَـٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَـٰرَىٰ تُفَـٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَـٰبِ وَتَكْفُرُونَ بِبَعْضٍ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","meal_tr":"Bütün bunlardan sonra siz şu insanlarsınız: Birbirinizi öldürüyorsunuz. İçinizden bir zümreyi yurtlarından çıkarıyorsunuz. Onlar aleyhine kötülük ve düşmanlık hususunda dayanışmaya giriyorsunuz. Esasında onları yurtlarından çıkarmak size haram edildiği halde, esir olarak size geldiklerinde fidyelerini veriyorsunuz. Şimdi siz Kitap'ın bir kısmına inanıp bir kısmını inkâr mı ediyorsunuz? İçinizden bunu yapanın cezası, dünya hayatında rezillikten başka bir şey değildir. Kıyamet gününde ise böyleleri azabın en şiddetlisine itilir. Allah, yapmakta olduklarınızdan habersiz değildir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ama siz, birbirinizi öldüren, içinizden bir kesime karşı kötülük ve zulümde yardımlaşarak; size haram olduğu halde onları yurtlarından çıkaran, size esir olarak geldiklerinde ise, fidye verip kendilerini kurtaran kimselersiniz. Yoksa siz Kitab'ın (Tevrat'ın) bir kısmına inanıp, bir kısmını inkâr mı ediyorsunuz? Artık sizden bunu yapanın cezası, dünya hayatında rezil olmaktan başka bir şey değildir. Kıyamet gününde ise onlar azabın en şiddetlisine uğratılırlar. Çünkü Allah yaptıklarınızdan habersiz değildir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1267.84,"audio_end":1312.66,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:86":{"sure_no":2,"ayet_no":86,"arapca":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ","meal_tr":"İşte bunlar, âhıret karşılığında dünyayı satın alan kişilerdir. Azap, hafifletilmeyecektir onlardan. Hiç bir şekilde yardım da edilmeyecektir onlara.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar, ahireti verip dünya hayatını satın alan kimselerdir. Artık bunlardan azap hiç hafifletilmez. Onlara yardım da edilmez.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1312.66,"audio_end":1323,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:87":{"sure_no":2,"ayet_no":87,"arapca":"وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ","meal_tr":"Yemin olsun ki, Mûsa'ya Kitap'ı verdik. Ve arkasından da resuller gönderdik. Meryem oğlu İsa'ya da açık-seçik deliller verdik ve kendisini Ruhulkudüs'le güçlendirdik. Bir resulün size, nefislerinizin hoşlanmadığı bir şey getirdiği her seferinde büyüklük taslamadınız mı? Bir kısmını yalanladınız, bir kısmını da öldürüyorsunuz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Andolsun, Mûsâ'ya Kitabı (Tevrat'ı) verdik. Ondan sonra ardarda peygamberler gönderdik. Meryemoğlu İsa'ya mucizeler verdik. Onu Ruhu'l-Kudüs (Cebrail) ile destekledik. Size herhangi bir peygamber, hoşunuza gitmeyen bir şey getirdikçe, kibirlenip (onların) bir kısmını yalanlayıp bir kısmını da öldürmediniz mi?","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1323,"audio_end":1348.5,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:88":{"sure_no":2,"ayet_no":88,"arapca":"وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ ۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ","meal_tr":"\"Kalplerimiz kabuk tutmuştur.\" dediler. Hayır öyle değil. Küfürleri yüzünden Allah onları lanetlemiştir de çok az bir kısmı iman eder.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Kalplerimiz muhafazalıdır\" dediler. Öyle değil. İnkarları sebebiyle Allah onları lânetlemiştir. Bu yüzden pek az iman ederler.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1348.5,"audio_end":1360,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:89":{"sure_no":2,"ayet_no":89,"arapca":"وَلَمَّا جَآءَهُمْ كِتَـٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَـٰفِرِينَ","meal_tr":"Yanlarındakini doğrulamak üzere kendilerine Allah katından bir kitap geldiğinde, daha önce inkâr edenlere karşı zafer isteyip durdukları halde, tanıyıp bildikleri kendilerine gelince, onu inkâr ettiler. Küfre sapanların üstüne olsun Allah'ın laneti!...","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Kendilerine ellerindekini (Tevrat'ı) tasdik eden bir kitap (Kur'an) gelince onu inkar ettiler. Oysa, daha önce (bu kitabı getirecek peygamber ile) inkarcılara (Arap müşriklerine) karşı yardım istiyorlardı. (Tevrat'tan) tanıyıp bildikleri (bu peygamber) kendilerine gelince ise onu inkar ettiler. Allah'ın lâneti inkarcıların üzerine olsun.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1360,"audio_end":1388.72,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:90":{"sure_no":2,"ayet_no":90,"arapca":"بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ","meal_tr":"Allah'ın, kullarından dilediğine lütfunun eseri olarak indirdiğini zalimce kıskanarak, Allah'ın vahyettiğini inkar etmeleri uğruna öz benliklerini sattıkları şey ne çirkindir! Bu yüzdendir ki gazap üzerine gazaba çarpıldılar. Gerçeği örtenler için rezil edici bir azap vardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Allah’ın, kullarından dilediğine peygamberlik ihsan etmesini kıskandıkları için Allah’ın indirdiğini (Kur’an’ı da) inkâr karşılığında kendilerini harcamaları ne kötü şeydir! Böylece onlar gazap üstüne gazaba uğradılar. Kâfirler için alçaltıcı bir azap vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1388.72,"audio_end":1409.3,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:91":{"sure_no":2,"ayet_no":91,"arapca":"وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ","meal_tr":"Onlara, \"Allah'ın indirmiş olduğuna inanın\" denildiğinde şöyle konuşurlar: \"Biz, bize indirilene inanırız.\" Ve ondan ötesini inkâr ederler. Oysaki o, kendilerinin yanındakini doğrulayıcı bir gerçektir. Söyle onlara: \"Madem iman sahibiydiniz, daha önce Allah'ın peygamberlerini niye öldürüyordunuz?\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlara, \"Allah'ın indirdiğine (Kur'an'a) iman edin\" denilince, \"Biz sadece bize indirilene (Tevrat'a) inanırız\" deyip, ondan sonra geleni (Kur'an'ı) inkâr ederler. Halbuki o ellerinde bulunanı (Tevrat'ı) tasdik eden hak bir kitaptır. De ki, \"Eğer inanan kimseler idiyseniz daha önce niçin Allah'ın peygamberlerini öldürüyordunuz?\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1409.3,"audio_end":1436.2,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:92":{"sure_no":2,"ayet_no":92,"arapca":"وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَـٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ","meal_tr":"Yemin olsun ki, Mûsa size açık-seçik hak beyanlarla gelmişti de onun arkasından buzağıyı ilâh edinmiştiniz. Zalimlersiniz sizler.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Andolsun, Mûsâ size açık mucizeler getirmişti de, arkasından sizler nefislerinize zulüm ederek buzağıyı ilah edinmiştiniz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1436.2,"audio_end":1446.08,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:93":{"sure_no":2,"ayet_no":93,"arapca":"وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَـٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ","meal_tr":"Hani kesin söz almıştık sizden de Tûr'u üzerinize kaldırmıştık. \"Size verdiğimizi kuvvetlice tutun ve dinleyin.\" demiştik. Şöyle demişlerdi: \"Dinledik ve isyan ettik.\" İnkârları yüzünden gönüllerine buzağı içirildi. De ki: \"Eğer inanan kişilerseniz, ne kötü şeydir size imanınızın emretmekte olduğu...\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, Tûr'u tepenize dikerek sizden söz almıştık, \"Size verdiğimiz Kitab'a sımsıkı sarılın; ona kulak verin\" demiştik. Onlar, \"Dinledik, karşı geldik\" demişlerdi. İnkârları yüzünden buzağı sevgisi onların kalplerine sindirilmişti. Onlara de ki (Tevrat'a beslediğinizi iddia ettiğiniz) imanınızın size emrettiği şey ne kötüdür, eğer inanan kimselerseniz!","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1446.08,"audio_end":1476.68,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:94":{"sure_no":2,"ayet_no":94,"arapca":"قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ","meal_tr":"De ki: \"Allah katındaki âhıret yurdu diğer insanların değil de yalnız ve yalnız sizin ise, eğer doğru sözlü iseniz, hadi isteyin ölümü!\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"De ki: \"Eğer (iddia ettiğiniz gibi) Allah katındaki ahiret yurdu (cennet) diğer insanlar için değil de, yalnız sizinse ve doğru söyleyenler iseniz haydi ölümü temenni edin!\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1476.68,"audio_end":1491.36,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:95":{"sure_no":2,"ayet_no":95,"arapca":"وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ","meal_tr":"Ellerinin önden gönderdiği şeyler yüzünden ölümü hiç bir zaman istemeyeceklerdir. Allah, zalimleri çok iyi bilmektedir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Fakat kendi elleriyle önceden yaptıkları işler yüzünden ölümü hiçbir zaman temenni edemezler. Allah o zalimleri hakkıyla bilendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1491.36,"audio_end":1502.38,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:96":{"sure_no":2,"ayet_no":96,"arapca":"وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ","meal_tr":"Sen onları, insanların yaşamaya en düşkünü olarak bulursun. Şirke batanlardan bile... Her biri bin yıl ömür sürsün ister. Oysa ki, uzun yaşaması onu azaptan uzaklaştıracak değildir. Allah, yapmakta olduklarını çok iyi görmektedir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Andolsun, sen onların, yaşamaya, bütün insanlardan; hatta Allah'a ortak koşanlardan bile daha düşkün olduklarını görürsün. Onların her biri bin yıl yaşamak ister. Halbuki uzun yaşamak onları azaptan kurtaracak değildir. Allah onların bütün işlediklerini görür.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1502.38,"audio_end":1525.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:97":{"sure_no":2,"ayet_no":97,"arapca":"قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ","meal_tr":"De ki: \"Kim Cebrail'e - ki o, Allah'ın izniyle Kur'an'ı kendinden öncekini doğrulayıcı, insanlara yol gösterici ve müjde olarak senin kalbine indirmiştir - düşman kesilirse,","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"De ki: \"Her kim Cebrail'e düşman ise, bilsin ki o, Allah'ın izni ile Kur'an'ı; önceki kitapları doğrulayıcı, mü'minler için de bir hidayet rehberi ve müjde verici olarak senin kalbine indirmiştir.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1525.22,"audio_end":1540.48,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:98":{"sure_no":2,"ayet_no":98,"arapca":"مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَـٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَـٰفِرِينَ","meal_tr":"Kim Allah'a, O'nun meleklerine, resullerine, Cebrail'e, Mikâil'e düşman kesilirse, Allah da bu tür inkârcılara düşman kesilir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Her kim Allah'a, meleklerine, peygamberlerine, Cebrail'e ve Mîkâil'e düşman olursa bilsin ki, Allah da inkar edenlerin düşmanıdır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1540.48,"audio_end":1551.68,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:99":{"sure_no":2,"ayet_no":99,"arapca":"وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۖ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَـٰسِقُونَ","meal_tr":"And olsun, biz sana açık-seçik ayetler indirdik. Onları, pislik ve sapıklığa bulaşmış olanlardan başkası inkâr etmez.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Andolsun, biz sana apaçık âyetler indirdik. Bunları ancak fasıklar inkâr eder.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1551.68,"audio_end":1557.74,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:100":{"sure_no":2,"ayet_no":100,"arapca":"أَوَكُلَّمَا عَـٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ","meal_tr":"Bir ahitle söz verdikleri her seferinde, içlerinden bir fırka ahdi kaldırıp atmadı mı? Doğrusu şu ki, onların çokları iman etmezler.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar ne zaman bir antlaşma yaptılarsa içlerinden bir takımı o antlaşmayı bozmadı mı? Zaten onların çoğu iman etmez.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1557.74,"audio_end":1568.06,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:101":{"sure_no":2,"ayet_no":101,"arapca":"وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ كِتَـٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ","meal_tr":"Allah katından kendilerine, ellerinde bulunanı tasdikleyici bir resul geldiğinde, kitap verilenlerden bir fırka, Allah'ın Kitabı'nı hiç bilmiyorlarmış gibi kaldırıp arkalarına attılar.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlara, Allah katından ellerinde bulunan Kitabı (Tevrat'ı) doğrulayıcı bir peygamber gelince, kendilerine kitap verilenlerden bir kısmı, sanki bilmiyorlarmış gibi Allah'ın Kitabı'nı (Tevrat'ı) arkalarına attılar.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1568.06,"audio_end":1586.68,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:102":{"sure_no":2,"ayet_no":102,"arapca":"وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَـٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَـٰنَ ۖ وَمَا كَفَرَ سُلَيْمَـٰنُ وَلَـٰكِنَّ ٱلشَّيَـٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَـٰرُوتَ وَمَـٰرُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ ۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ ۚ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ","meal_tr":"Süleyman'ın mülk ve saltanatı konusunda onlar, şeytanların okuyup durduklarına uydular. Halbuki Süleyman küfre sapmamıştı. Ancak şeytanlar küfre sapmıştı; insanlara büyüyü öğretiyorlardı. Ve Babil'de Hârût ve Mârût adlı iki melek üzerine indirileni öğretiyorlardı. Oysa ki o iki melek, \"Biz bir imtihan aracıyız, sakın küfre sapma!\" demedikçe hiç kimseye bir şey öğretmiyorlardı. İnsanlar onlardan erkekle eşinin arasını açacakları şeyi öğreniyorlardı. Ne var ki, onlar onunla Allah'ın izni olmadıkça hiç kimseye zarar veremezler. Onlar kendilerine zarar vereni, yarar vermeyeni öğreniyorlardı. Yemin olsun ki, onu satın alanın âhırette hiç bir nasibi olmayacağını açıkça bilmişlerdir. Öz benliklerini sattıkları şey ne kötüdür! Bir bilebilselerdi...","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Süleyman'ın hükümranlığı hakkında şeytanların (ve şeytan tıynetli insanların) uydurdukları yalanların ardına düştüler. Oysa Süleyman (büyü yaparak) küfre girmedi. Fakat şeytanlar, insanlara sihri ve (özellikle de) Babil'deki Hârût ve Mârût adlı iki meleğe ilham edilen (sihr)i öğretmek suretiyle küfre girdiler. Halbuki o iki melek, \"Biz ancak imtihan için gönderilmiş birer meleğiz. (Sihri caiz görüp de) sakın küfre girme\" demedikçe, kimseye (sihir) öğretmiyorlardı. Böylece (insanlar) onlardan kişi ile karısını birbirinden ayıracakları sihri öğreniyorlardı. Halbuki onlar, Allah'ın izni olmadıkça o sihirle hiç kimseye zarar veremezlerdi. (Onlar böyle yaparak) kendilerine zarar veren, fayda getirmeyen şeyleri öğreniyorlardı. Andolsun, onu satın alanın ahirette bir nasibi olmadığını biliyorlardı. Kendilerini karşılığında sattıkları şey ne kötüdür! Keşke bilselerdi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1586.68,"audio_end":1660.24,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:103":{"sure_no":2,"ayet_no":103,"arapca":"وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ ۖ لَّوْ كَانُوا۟ يَعْلَمُونَ","meal_tr":"Eğer onlar iman edip sakınsalardı, Allah katından bir sevap elbette daha kıymetli olurdu. Keşke bilebilselerdi.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Eğer onlar iman edip Allah'ın emirlerine karşı gelmekten sakınmış olsalardı, Allah katında kazanacakları sevap kendileri için daha hayırlı olacaktı. Keşke bilselerdi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1660.24,"audio_end":1676.28,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:104":{"sure_no":2,"ayet_no":104,"arapca":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ","meal_tr":"Ey iman edenler! \"Râina\" demeyin, \"unzurna\" deyin/\"bizi davar gibi güt\" diye konuşmayın, \"bize bak\" diye konuşun ve dinleyin. Kâfîrler için korkunç bir azap vardır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ey iman edenler! \"Râinâ\" (bizi gözet) demeyin, \"unzurnâ\" (bize bak) deyin ve dinleyin. Kafirler için acıklı bir azap vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1676.28,"audio_end":1685.32,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:105":{"sure_no":2,"ayet_no":105,"arapca":"مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ ۗ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","meal_tr":"Ehlikitap'ın küfre sapanlarıyla müşrikler, Rabb'inizden size bir hayır indirilmesini istemezler. Ama Allah, rahmetini dilediğine özgüler. Allah, büyük lütfun sahibidir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ne Kitab ehlinden inkâr edenler ve ne de Allah'a ortak koşanlar, Rabbinizden size bir iyilik gelmesini isterler. Oysa Allah rahmetini dilediğine tahsis eder. Allah, büyük lütuf sahibidir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1685.32,"audio_end":1701.5,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:106":{"sure_no":2,"ayet_no":106,"arapca":"مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","meal_tr":"Biz bir ayeti siler, unutturur veya ertelersek ondan daha iyisini veya onun bir benzerini getiririz. Allah'ın her şeye gücü yeter olduğunu bilmedin mi?","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Biz herhangi bir âyetin hükmünü yürürlükten kaldırır veya onu unutturur (ya da ertelersek), yerine daha hayırlısını veya mislini getiririz. Allah'ın gücünün her şeye hakkıyla yettiğini bilmez misin?","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1701.5,"audio_end":1718.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:107":{"sure_no":2,"ayet_no":107,"arapca":"أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ","meal_tr":"Bilmedin mi ki göklerin de yerin de mülk ve saltanatı yalnız Allah'ındır. Sizin için Allah'tan başka ne bir Velî vardır ne de bir Nasîr/yardımcı.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bilmez misin ki, göklerin ve yerin hükümranlığı Allah'ındır. Sizin için Allah'tan başka ne bir dost, ne de bir yardımcı vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1718.26,"audio_end":1728.86,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:108":{"sure_no":2,"ayet_no":108,"arapca":"أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","meal_tr":"Yoksa siz de resulünüzden, daha önce Mûsa'dan istekte bulunulduğu gibi isteklerde bulunmak mı diliyorsunuz?! İmanı küfürle değiştirmeye kalkan,yolun dosdoğrusunu saptırmış olur.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Yoksa, daha önce Mûsâ'nın sorguya çekildiği gibi, siz de peygamberinizi sorguya çekmek mi istiyorsunuz? Her kim imanı küfre değişirse, o artık doğru yoldan sapmış olur.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1728.86,"audio_end":1742.74,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:109":{"sure_no":2,"ayet_no":109,"arapca":"وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَـٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","meal_tr":"Ehlikitap'tan birçoğu, benliklerindeki kıskançlık yüzünden sizi, imanınızdan sonra kâfirler haline bir döndürebilseler diye yürekten istedi. Hem de gerçek kendilerine ayan-beyan olduktan sonra... Allah, buyruğunu getirinceye değin affedin, hoşgörün. Allah, her şeye gücü yetendir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Kitap ehlinden bir çoğu, hak kendilerine belirdikten sonra dahi, içlerindeki kıskançlıktan ötürü sizi, imanınızdan sonra küfre döndürmek isterler. Siz şimdilik, Allah onlar hakkındaki emrini getirinceye kadar affedin, hoşgörün. Şüphesiz Allah, gücü her şeye hakkıyla yetendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1742.74,"audio_end":1766.92,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:110":{"sure_no":2,"ayet_no":110,"arapca":"وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ","meal_tr":"Namazı kılın, zekatı verin. Öz benlikleriniz için önden gönderdiğiniz her hayrı, Allah katında bulacaksınız. Hiç kuşkusuz, Allah, yapmakta olduklarınızı iyice görmektedir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Namazı dosdoğru kılın, zekâtı verin. Kendiniz için her ne iyilik işlemiş olursanız, Allah katında onu bulursunuz. Şüphesiz Allah bütün yaptıklarınızı görür.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1766.92,"audio_end":1780.52,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:111":{"sure_no":2,"ayet_no":111,"arapca":"وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَـٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ إِن كُنتُمْ صَـٰدِقِينَ","meal_tr":"\"Yahudi yahut Hıristiyan olandan başkası cennete asla giremeyecek.\" dediler. Bu, onların hayalleri, kuruntularıdır. De ki onlara: \"Eğer doğru sözlü iseniz hadi getirin susturucu kanıtınızı!\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bir de; \"Yahudi ve Hıristiyanlardan başkası Cennet'e girmeyecek\" dediler. Bu, onların kuruntuları! De ki: \"Eğer doğru söyleyenler iseniz (iddianızı ispat edecek) delilinizi getirin.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1780.52,"audio_end":1795.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:112":{"sure_no":2,"ayet_no":112,"arapca":"بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","meal_tr":"İş onların sandığı gibi değil! Kim güzel davranışlar sergileyerek yüzünü Allah'a teslim ederse, Rabb'i katında ödülü vardır onun. Korku yoktur böyleleri için; tasalanmayacaklardır onlar...","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hayır, öyle değil! Kim \"ihsan\" derecesine yükselerek özünü Allah'a teslim ederse, onun mükâfatı Rabbinin katındadır. Artık onlara korku yoktur, onlar üzülmeyeceklerdir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1795.22,"audio_end":1809.48,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:113":{"sure_no":2,"ayet_no":113,"arapca":"وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَـٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَـٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَـٰبَ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ","meal_tr":"Yahudiler: \"Hıristiyanlar hiç bir şey üzerinde değil.\" dediler. Hıristiyanlar da: \"Yahudiler hiç bir şey üzerinde değil.\" dediler. Ve bunlar Kitap'ı da okuyup dururlar, ilimden yoksun olanlar da aynen onların söyledikleri gibi söyledi. Tartışmaya girdikleri şey hakkında, aralarında hükmü, kıyamet günü Allah verecektir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Yahudiler, \"Hıristiyanlar bir temel üzerinde değiller\" dediler. Hıristiyanlar da, \"Yahudiler bir temel üzerinde değiller\" dediler. Oysa hepsi Kitab'ı okuyorlar.(Kitab'ı) bilmeyenler de tıpkı bunların söyledikleri gibi demişti. Artık onların aralarında uyuşamadıkları davada, hükmü Allah verecektir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1809.48,"audio_end":1836.72,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:114":{"sure_no":2,"ayet_no":114,"arapca":"وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَـٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَـٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ","meal_tr":"Allah'ın mescitlerini, içlerinde O'nun adı anılıyor diye engelleyen ve onların yıkımı için uğraşan kişiden daha zalim kim olabilir!.. Böylelerinin, o mescitlere girmeleri ancak korka korka olacaktır. Böyleleri için dünyada bir rezillik vardır. Âhırette ise bunlara çok büyük bir azap öngörülmüştür.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Allah'ın mescitlerinde onun adının anılmasını yasak eden ve onların yıkılması için çalışandan kim daha zalimdir. Böyleleri oralara (eğer girerlerse) ancak korka korka girebilmelidirler. Bunlar için dünyada rezillik, ahirette de büyük bir azap vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1836.72,"audio_end":1858.54,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:115":{"sure_no":2,"ayet_no":115,"arapca":"وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ","meal_tr":"Doğu da batı da yalnız Allah'ındır. O halde nereye dönerseniz orada Allah'ın yüzü vardır. Allah Vâsi'dir, varlığı sürekli genişletip büyütür; Alîm'dir, her şeyi en iyi biçimde bilir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Doğu da, Batı da (tüm yeryüzü) Allah'ındır. Nereye dönerseniz Allah'ın yüzü işte oradadır. Şüphesiz Allah, lütfu geniş olandır, hakkıyla bilendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1858.54,"audio_end":1870.66,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:116":{"sure_no":2,"ayet_no":116,"arapca":"وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ بَل لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّ لَّهُۥ قَـٰنِتُونَ","meal_tr":"\"Allah çocuk edindi.\" dediler. Haşâ! Böyle bir şeyden arınmıştır O! Tam aksine, göklerdekiler de yerdekiler de O'na aittir. Bunların tümü O'nun önünde boyun bükmektedir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Allah, çocuk edindi\" dediler. O, bundan uzaktır. Hayır! Göklerdeki ve yerdeki her şey Allah'ındır. Hepsi O'na boyun eğmiştir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1870.66,"audio_end":1881.14,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:117":{"sure_no":2,"ayet_no":117,"arapca":"بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","meal_tr":"Gökleri ve yeri, güzelliklerle donatarak yaratan Bedî, O'dur. Bir şeyin olmasına karar verdi mi ona sadece \"Ol'\" der. Artık o, oluverir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"O, gökleri ve yeri örneksiz yaratandır. Bir işe hükmetti mi ona sadece \"ol\" der, o da hemen oluverir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1881.14,"audio_end":1888.7,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:118":{"sure_no":2,"ayet_no":118,"arapca":"وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَـٰبَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا ٱلْـَٔايَـٰتِ لِقَوْمٍ يُوقِنُونَ","meal_tr":"Bilgiden yoksun olanlar dedi ki: \"Allah bizimle konuşsaydı yahut bize bir mucize gelseydi ya!...\" Onlardan öncekiler de aynen onların dediği gibi demişti. Kalpleri birbirine benzemiştir. Biz ayetleri, gerçeği apaçık bilmek isteyenler için iyiden iyiye açıklamışızdır.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bilmeyenler, \"Allah bizimle konuşsa, ya da bize bir mucize gelse ya!\" derler. Bunlardan öncekiler de tıpkı böyle, bunların dedikleri gibi demişti. Onların kalpleri (anlayışları) birbirine benziyor. Biz âyetleri, kesin olarak inanacak bir toplum için açıkladık.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1888.7,"audio_end":1910.7,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:119":{"sure_no":2,"ayet_no":119,"arapca":"إِنَّآ أَرْسَلْنَـٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا ۖ وَلَا تُسْـَٔلُ عَنْ أَصْحَـٰبِ ٱلْجَحِيمِ","meal_tr":"İnan olsun ki, biz seni hak üzere bir müjdeci ve uyarıcı olarak gönderdik. Sen, cehennem ehlinden sorgu suale çekilmeyeceksin/cehennem yâranından sen sorumlu değilsin.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Şüphesiz biz seni hak ile; müjdeleyici ve uyarıcı olarak gönderdik. Sen cehennemlik olanlardan sorumlu tutulacak değilsin.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1910.7,"audio_end":1921.12,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:120":{"sure_no":2,"ayet_no":120,"arapca":"وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَـٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ","meal_tr":"Sen onların öz milletlerine uymadıkça Yahudiler de Hıristiyanlar da senden asla hoşnut olmazlar. De ki: \"Allah'ın kılavuzluğu erdirici kılavuzluğun ta kendisidir.\" İlimden sana ulaşan nasipten sonra bunların boş ve iğreti arzularına uyarsan, Allah katından ne bir Velî'n olur ne de bir yardımcın.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Sen dinlerine uymadıkça, ne Yahudiler ve ne de Hıristiyanlar asla senden razı olmazlar. De ki: \"Allah'ın yolu asıl doğru yoldur.\" Sana gelen ilimden sonra, eğer onların arzu ve keyiflerine uyacak olursan, bilmiş ol ki, Allah'tan sana ne bir dost, ne bir yardımcı vardır.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1921.12,"audio_end":1943.1,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:121":{"sure_no":2,"ayet_no":121,"arapca":"ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۗ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ","meal_tr":"Kendilerine Kitap'ı verdiklerimiz onu, okunuşunun hakkını vererek okurlar. İşte onlar ona inanırlar. Onu inkar edenlere gelince, onlar hüsrana uğrayanların ta kendileridir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Kendilerine kitab verdiğimiz kimseler, onu gereği gibi okurlar. İşte bunlar ona inanırlar. Onu inkar edenlere gelince, işte onlar ziyana uğrayanların ta kendileridir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1943.1,"audio_end":1957,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:122":{"sure_no":2,"ayet_no":122,"arapca":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ","meal_tr":"Ey İsrailoğulları! Size lütfettiğim nimetimi hatırlayın. Ben sizi âlemlerden daha üstün kılmıştım.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Ey İsrailoğulları! Size verdiğim nimetimi ve (bir zamanlar) sizi cümle âleme üstün tuttuğumu hatırlayın.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1957,"audio_end":1965.78,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:123":{"sure_no":2,"ayet_no":123,"arapca":"وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَـٰعَةٌ وَلَا هُمْ يُنصَرُونَ","meal_tr":"Kimsenin kimse yerine bir şey ödemeyeceği, kimseden fidye kabul edilmeyeceği, şefaatin hiç kimseye yarar sağlamayacağı ve onların hiç bir yardım göremeyecekleri o günden korkun.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Kimsenin kimse namına bir şey ödemeyeceği, hiç kimseden fidye alınmayacağı, kimseye şefaatin (aracılığın) yarar sağlamayacağı ve hiç kimsenin hiçbir taraftan yardım göremeyeceği günden sakının.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1965.78,"audio_end":1982.98,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:124":{"sure_no":2,"ayet_no":124,"arapca":"وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَـٰتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّـٰلِمِينَ","meal_tr":"Hani Rabb'i, İbrahim'i bazı kelimelerle imtihana çekmiş, o da onların hakkını vermişti de Rab şöyle demişti: \"Seni insanlara önder yapacağım.\" İbrahim, \"soyumdan birilerini de\" deyince Allah: \"Benim ahdime zalimler eremezler.\" buyurdu.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Bir zaman Rabbi İbrahim'i bir takım emirlerle sınamış, İbrahim onların hepsini yerine getirmiş de Rabbi şöyle buyurmuştu: \"Ben seni insanlara önder yapacağım.\" İbrahim de, \"Soyumdan da (önderler yap, ya Rabbi!)\" demişti. Bunun üzerine Rabbi, \"Benim ahdim (verdiğim söz) zalimleri kapsamaz\" demişti.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":1982.98,"audio_end":2007.62,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:125":{"sure_no":2,"ayet_no":125,"arapca":"وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى ۖ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَـٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ","meal_tr":"Hatırla o zamanı ki, biz Beytullah'ı insanlar için sevap kazanmaya yönelik bir toplantı yeri ve güvenli bir sığınak yaptık. Siz de İbrahim'in makamından bir dua yeri edinin. İbrahim ve İsmail'e şu sözü ulaştırmıştık; \"Tavaf edenler, kendini ibadete verenler, rükû-secde edenler için evimi temizleyin!\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani, biz Kâbe'yi insanlara toplantı ve güven yeri kılmıştık. Siz de Makam-ı İbrahim'den kendinize bir namaz yeri edinin. İbrahim ve İsmail'e şöyle emretmiştik: \"Tavaf edenler, kendini ibadete verenler, rukû ve secde edenler için evimi (Kâbe'yi) tertemiz tutun.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2007.62,"audio_end":2028.66,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:126":{"sure_no":2,"ayet_no":126,"arapca":"وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَـٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ ۖ وَبِئْسَ ٱلْمَصِيرُ","meal_tr":"İbrahim şöyle yakarmıştı: \"Rabb'im! Şu kenti güvenli bir kent yap, halkının Allah'a ve âhıret gününe inananlarını çeşitli ürünlerle rızklandır.\" Rab dedi ki: \"Küfre sapanları bile rızklandırırım. Ama az bir nimetle rızklandırır, sonra da ateş azabına itiveririm. Ne kötü bir dönüş yeridir o...\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani İbrahim, \"Rabbim! Bu şehri güvenli bir şehir kıl. Halkından Allah'a ve ahiret gününe iman edenleri her türlü ürünle rızıklandır\" demişti. Allah da, \"İnkâr edeni bile az bir süre, (bu geçici kısa hayatta) rızıklandırır; sonra onu cehennem azabına girmek zorunda bırakırım. Ne kötü varılacak yerdir orası!\" demişti.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2028.66,"audio_end":2055.12,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:127":{"sure_no":2,"ayet_no":127,"arapca":"وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَـٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ","meal_tr":"İbrahim'in, İsmail'le birlikte, Beytullah'ın ana duvarlarını yükselterek şöyle yakardıkları zamanı da an: \"Rabb'imiz, bizden gelen niyazları kabul buyur; sen, evet sen, Semî'sin, her şeyi çok iyi duyarsın; Alîm'sin, her şeyi çok iyi bilirsin.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Hani İbrahim, İsmail ile birlikte evin (Kâbe'nin) temellerini yükseltiyor, \"Ey Rabbimiz! Bizden kabul buyur! Şüphesiz sen hakkıyla işitensin, hakkıyla bilensin\" diyorlardı.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2055.12,"audio_end":2070.18,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:128":{"sure_no":2,"ayet_no":128,"arapca":"رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","meal_tr":"\"Rabb'imiz! Bizi, sana teslim olmuş iki müslüman kıl. Soyumuzdan da sana teslim olan müslüman bir ümmet oluştur. Bize ibadet yerlerimizi göster, bizim tövbemizi kabul et. Sen, evet sen, Tevvâb'sın, tövbeleri cömertçe kabul edersin; Rahîm'sin, rahmetini cömertçe yayarsın.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Rabbimiz! Bizi sana teslim olmuş kimseler kıl. Soyumuzdan da sana teslim olmuş bir ümmet kıl. Bize ibadet yerlerini ve ilkelerini göster. Tövbemizi kabul et. Çünkü sen, tövbeleri çok kabul edensin, çok merhametli olansın.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2070.18,"audio_end":2088.1,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:129":{"sure_no":2,"ayet_no":129,"arapca":"رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","meal_tr":"\"Rabb'imiz! İçlerinden onlara, senin ayetlerini okuyacak, kendilerine Kitap'ı ve hikmeti öğretecek, onları temizleyip arındıracak bir resul gönder. Sen, evet sen, Azîz'sin, tüm ululuk ve onurun sahibisin; Hakîm'sin, tüm hikmetlerin kaynağısın.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Rabbimiz! İçlerinden onlara bir peygamber gönder; onlara âyetlerini okusun, kitabı ve hikmeti öğretsin ve onları her kötülükten arındırsın. Şüphesiz, sen mutlak güç sahibisin, hüküm ve hikmet sahibisin.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2088.1,"audio_end":2105.76,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:130":{"sure_no":2,"ayet_no":130,"arapca":"وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ ۚ وَلَقَدِ ٱصْطَفَيْنَـٰهُ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ","meal_tr":"Öz benliğini beyinsizliğe itenden başka kim, İbrahim'in milletinden yüz çevirir? Yemin olsun ki biz onu dünyada seçip yüceltmiştik. Ve o, âhırette de barış ve iyilik sevenlerden biri olacaktır elbette...","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Kendini bilmeyenden başka İbrahim'in dininden kim yüz çevirir? Andolsun, biz İbrahim'i bu dünyada seçkin kıldık. Şüphesiz o ahirette de iyilerdendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2105.76,"audio_end":2118.36,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:131":{"sure_no":2,"ayet_no":131,"arapca":"إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَـٰلَمِينَ","meal_tr":"Rabb'i ona, \"Müslüman olup bana teslim ol!\" dediğinde o şu cevabı vermişti: \"Teslim oldum âlemlerin Rabb'ine!\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Rabbi ona \"Teslim ol\" dediğinde \"Âlemlerin Rabbine teslim oldum\" demişti.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2118.36,"audio_end":2124.2,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:132":{"sure_no":2,"ayet_no":132,"arapca":"وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَـٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ","meal_tr":"İbrahim de oğullarına şunu vasiyet etti, Yakub da: \"Oğullarım! Allah sizin için bu dini seçmiştir. O halde ancak müslümanlar olarak can verin.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"İbrahim bunu kendi oğullarına da vasiyet etti, Yakub da öyle: \"Oğullarım! Allah sizin için bu dini (İslâm'ı) seçti. Siz de ancak müslümanlar olarak ölün\" dedi.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2124.2,"audio_end":2137.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:133":{"sure_no":2,"ayet_no":133,"arapca":"أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَـٰهَكَ وَإِلَـٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ إِلَـٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ","meal_tr":"Yoksa siz, Yakub'a ölümün gelip çatışına tanıklar mıydınız? Hani, oğullarına şunu sormuştu: \"Benden sonra neye ibadet edeceksiniz?\" Cevapları şu olmuştu: \"Senin ilâhına, ataların İbrahim'in, İsmail'in, İshak'ın ilâhına, tek ve biricik olan ilâha kulluk edeceğiz; biz yalnız O'na teslim olanlarız.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Yoksa siz Yakub'un, ölüm döşeğinde iken çocuklarına, \"Benden sonra kime ibadet edeceksiniz?\" dediği, onların da, \"Senin ilahına ve ataların İbrahim, İsmail ve İshak'ın ilahı olan tek bir ilâha ibadet edeceğiz; bizler ona boyun eğmiş müslümanlarız.\" dedikleri zaman orada hazır mı bulunuyordunuz?","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2137.22,"audio_end":2162.36,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:134":{"sure_no":2,"ayet_no":134,"arapca":"تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ","meal_tr":"İşte bunlar bir ümmetti, gelip geçtiler. Kazandıkları kendilerinindir. Sizin kazandıklarınız da sizin olacaktır. Siz onların yapıp ettiklerinden sorguya çekilmeyeceksiniz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar gelip geçmiş bir ümmettir. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorumlu tutulacak değilsiniz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2162.36,"audio_end":2176.36,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:135":{"sure_no":2,"ayet_no":135,"arapca":"وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَـٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","meal_tr":"\"Yahudi yahut Hıristiyan olun ki doğruya kılavuzlanasınız.\" dediler. De ki: \"Hayır, öyle değil. Şirk ve yozlaşmadan uzak bir biçimde, İbrahim milletinden olalım. O, şirke bulaşanlardan değildi.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"(Yahudiler) \"Yahudi olun\" ve (Hıristiyanlar da) \"Hıristiyan olun ki doğru yolu bulasınız\" dediler. De ki: \"Hayır, hakka yönelen İbrahim'in dinine uyarız. O, Allah'a ortak koşanlardan değildi.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2176.36,"audio_end":2191.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:136":{"sure_no":2,"ayet_no":136,"arapca":"قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ","meal_tr":"Şöyle deyin: \"Allah'a, bize indirilene, İbrahim'e, İsmail'e, İshak'a, Yakub'a, onun torunlarına indirilene, Mûsa'ya ve İsa'ya verilene ve diğer nebilere verilene inandık. Bunlar arasından hiç kimseyi ayırmayız. Biz yalnız O'na/Allah'a teslim olanlarız.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Deyin ki: \"Biz Allah'a, bize indirilene (Kur'an'a), İbrahim, İsmail, İshak, Yakub ve Yakuboğullarına indirilene, Mûsâ ve İsa'ya verilen (Tevrat ve İncil) ile bütün diğer peygamberlere Rab'lerinden verilene iman ettik. Onlardan hiçbirini diğerinden ayırt etmeyiz ve biz ona teslim olmuş kimseleriz.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2191.22,"audio_end":2216.12,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:137":{"sure_no":2,"ayet_no":137,"arapca":"فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ ۖ فَسَيَكْفِيكَهُمُ ٱللَّهُ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","meal_tr":"Eğer onlar da sizin inandığınız gibi inanırlarsa, hiç kuşkusuz iyiyi ve güzeli bulmuş olurlar; eğer sırt dönerlerse artık onlar şıkak içindedirler/parçalanmış olurlar. Onlara karşı sana Allah yeter. En iyi işiten, en güzel bilendir O.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Eğer onlar böyle sizin iman ettiğiniz gibi iman ederlerse gerçekten doğru yolu bulmuş olurlar; yüz çevirirlerse onlar elbette derin bir ayrılığa düşmüş olurlar. Allah onlara karşı seni koruyacaktır. O, hakkıyla işitendir, hakkıyla bilendir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2216.12,"audio_end":2237.22,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:138":{"sure_no":2,"ayet_no":138,"arapca":"صِبْغَةَ ٱللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً ۖ وَنَحْنُ لَهُۥ عَـٰبِدُونَ","meal_tr":"Allah'ın boyasını esas alın. Allah'tan daha güzel kim boya vurabilir! Biz yalnız O'na kulluk ederiz.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"\"Biz Allah'ın boyasıyla boyanmışızdır. Boyası Allah'ınkinden daha güzel olan kimdir? Biz ona ibadet edenleriz\" (deyin).","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2237.22,"audio_end":2246.52,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:139":{"sure_no":2,"ayet_no":139,"arapca":"قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ","meal_tr":"De ki onlara: \"Allah hakkında bizimle tartışıyor musunuz? Oysaki Allah hem bizim Rabb'imizdir hem sizin Rabb'inizdir. Bizim amellerimiz bize, sizin amelleriniz size. Biz yalnız O'na/Allah'a gönül verenleriz.\"","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlara de ki: \"Allah hakkında mı bizimle tartışıp duruyorsunuz? Halbuki O, bizim de Rabbimiz, sizin de Rabbinizdir. Bizim işlediklerimiz bize, sizin işledikleriniz size aittir. Biz ona gönülden bağlanmış kimseleriz.\"","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2246.52,"audio_end":2265.26,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:140":{"sure_no":2,"ayet_no":140,"arapca":"أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَـٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","meal_tr":"Yoksa siz, \"İbrahim, İsmail, İshak, Yakub ve torunları Yahudi yahut Hıristiyanlardı\" mı diyorsunuz? Söyle onlara: \"Siz mi daha bilgilisiniz yoksa Allah mı?\" Allah'tan kendine ulaşmış bir tanıklığı gizleyenden daha zalim kim vardır! Allah, yapmakta olduklarınızdan habersiz değildir.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Yoksa siz, \"İbrahim de, İsmail de, İshak da, Yakub ile Yakuboğulları da yahudi, ya da hıristiyan idiler\" mi diyorsunuz? De ki: \"Sizler mi daha iyi bilirsiniz, yoksa Allah mı?\" Allah tarafından kendisine ulaşan bir gerçeği gizleyen kimseden daha zalim kimdir? Allah yaptıklarınızdan habersiz değildir.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2265.26,"audio_end":2290.58,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"},"2:141":{"sure_no":2,"ayet_no":141,"arapca":"تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ","meal_tr":"İşte bunlar bir ümmetti, gelip geçtiler. Kazandıkları kendilerine. Sizin kazandığınız da size. Onların yapıp ettiklerinden siz sorumlu olmayacaksınız.","meal_kaynagi":"Yaşar Nuri Öztürk","diyanet_tr":"Onlar gelip geçmiş bir ümmettir. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorumlu tutulacak değilsiniz.","diyanet_kaynagi":"Diyanet İşleri Başkanlığı Meali","meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_meal_source_id":"diyanet-isleri-baskanligi-meali-1","audio_src":"https://audios.tmgrup.com.tr/i.tmgrup.com.tr/fikriyat/2019/12/27/b6e798d7-ed88-485b-a774-9c8a3733cc97/1577452395285.mp3","audio_start":2290.58,"audio_end":2304.62,"audio_verified":true,"audio_voice":"Mazlum Kiper","audio_cuz":1,"alignment_method":"silence-boundary-v1+7-independent-anchors"}}};
